function isDefined<T>(val: T | null | undefined): val is T {
  return val !== null && val !== undefined;
}
const valid = [1, null, 2, undefined].filter(isDefined);

type Prettify<T> = {
  [K in keyof T]: T[K];
} & {};

type UserProfile = Prettify<User & { role: 'admin' | 'guest' }>;

interface Repository<T extends { id: string }> {
  findById(id: string): Promise<T | null>;
  save(entity: T): Promise<void>;
  delete(id: string): Promise<boolean>;
}

type NonEmptyArray<T> = [T, ...T[]];

function head<T>(arr: NonEmptyArray<T>): T {
  return arr[0];
}

type KeysOfType<T, U> = {
  [K in keyof T]: T[K] extends U ? K : never;
}[keyof T];

const assertNever = (value: never): never => {
  throw new Error(`Unexpected value: ${JSON.stringify(value)}`);
};

type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object
    ? DeepReadonly<T[K]>
    : T[K];
};

export interface Store<T> {
  readonly value: T;
  subscribe(listener: (val: T) => void): () => void;
  set(next: T): void;
}

async function retry<T>(
  fn: () => Promise<T>,
  retries: number = 3,
  delayMs: number = 500
): Promise<T> {
  try {
    return await fn();
  } catch (err) {
    if (retries <= 0) throw err;
    await new Promise((r) => setTimeout(r, delayMs));
    return retry(fn, retries - 1, delayMs * 2);
  }
}

type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends (infer U)[]
    ? DeepPartial<U>[]
    : T[P] extends object
    ? DeepPartial<T[P]>
    : T[P];
};

type Path<T> = T extends object
  ? { [K in keyof T]: `${Exclude<K, symbol>}${Path<T[K]> extends "" ? "" : `.${Path<T[K]>}`}` }[keyof T]
  : "";

class Result<T, E = Error> {
  private constructor(
    private readonly _value?: T,
    private readonly _error?: E
  ) {}
  static ok<T>(value: T): Result<T, never> {
    return new Result<T, never>(value, undefined);
  }
  static err<E>(error: E): Result<never, E> {
    return new Result<never, E>(undefined, error);
  }
  isOk(): this is { unwrap(): T } {
    return this._error === undefined;
  }
  unwrap(): T {
    if (this._error !== undefined) throw this._error;
    return this._value!;
  }
}
